            aOrbiterD = ((aOrbiterD ^ aOrbiterG) ^ 0xCEC433817223CB50ULL) ^ aSeedOrbiterUpdateSaltF[((aIndex + 20U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x875D71D3B3706EF1ULL), 19U);
