            //
            aWandererE = aWandererE ^ ((RotL64(aCross, 29U) + RotL64(aOrbiterI, 51U)) + aOrbiterK);
            aWandererD = aWandererD + ((((RotL64(aPrevious, 13U) + RotL64(aOrbiterK, 43U)) + aOrbiterC) + RotL64(aCarry, 23U)) + aTwistWandererUpdateSaltC[((aIndex + 11U)) & S_SALT1]);
            aWandererK = aWandererK ^ ((RotL64(aScatter, 57U) + aOrbiterB) + RotL64(aOrbiterH, 11U));
            aWandererB = aWandererB + ((((RotL64(aIngress, 5U) + RotL64(aOrbiterG, 21U)) + aOrbiterH) + RotL64(aCarry, 37U)) + aTwistWandererUpdateSaltD[((aIndex + 24U)) & S_SALT1]);
            aWandererG = aWandererG ^ ((RotL64(aScatter, 19U) + RotL64(aOrbiterK, 3U)) + aOrbiterG);
