            aOrbiterB = (((aWandererD + RotL64(aScatter, 5U)) + RotL64(aCarry, 43U)) + 0x9BA271E7506C614FULL) + aTwistOrbiterAssignSaltC[(((31U - aIndex) + 12U)) & S_SALT1];
            aOrbiterC = (aWandererF + RotL64(aCross, 21U)) + 0xC41FD2F9120F1663ULL;
            aOrbiterD = ((aWandererA + RotL64(aPrevious, 30U)) + RotL64(aCarry, 27U)) + 0xE462D537D0C0C112ULL;
            aOrbiterF = (aWandererI + RotL64(aIngress, 51U)) + 0x876CEC9D0FEDB13EULL;
            aOrbiterK = (aWandererB + RotL64(aPrevious, 37U)) + 0xBD37DD4D0478972EULL;
            aOrbiterH = ((aWandererJ + RotL64(aCross, 43U)) + 0xA89E9511CEC265B2ULL) + aTwistOrbiterAssignSaltB[((aIndex + 29U)) & S_SALT1];
