            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0xC7E824673242144CULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterB) ^ 0x5ADD4DAFA7E8BC51ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x9AA1C80E1C447425ULL), 57U);
