            aOrbiterH = RotL64((aOrbiterH * 0x7922CB3E49A4B025ULL), 13U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterE) + 0x0BBA74DF9E1F8339ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterC) ^ 0x09961AB71FD6CA67ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xE9219E226E0502EDULL), 21U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterH) + 0xBD4ECFDC27B222F4ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterK) ^ 0x51379AB84A2A0E20ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xDD608768A669A929ULL), 43U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterD) + 0x9D919301F437E577ULL) + aTwistOrbiterUpdateSaltC[((aIndex + 14U)) & S_SALT1];
            aOrbiterK = ((aOrbiterK ^ aOrbiterE) ^ 0xF38D10895639BC5AULL) ^ aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 15U)) & S_SALT1];
