            aWandererB = aWandererB ^ (((RotL64(aPrevious, 41U) + aOrbiterB) + RotL64(aOrbiterD, 37U)) + aTwistWandererUpdateSaltB[(((31U - aIndex) + 17U)) & S_SALT1]);
