            aIngress = (RotL64(aFuseLaneB[((aIndex + 21456U)) & S_BLOCK1], 5U) ^ RotL64(aWaterLaneD[((aIndex + 19683U)) & S_BLOCK1], 13U));
            aIngress ^= (RotL64(aFireLaneA[((aIndex + 21704U)) & S_BLOCK1], 44U) ^ RotL64(aFireLaneC[((aIndex + 20736U)) & S_BLOCK1], 29U));
            aIngress = TwistMix64::DiffuseC(aIngress);
            //
            aCross = (RotL64(aFuseLaneA[((S_BLOCK1 - aIndex + 22442U)) & S_BLOCK1], 21U) ^ RotL64(aWaterLaneB[((S_BLOCK1 - aIndex + 19385U)) & S_BLOCK1], 56U));
            aCross ^= RotL64(aEarthLaneB[((aIndex + 20969U)) & S_BLOCK1], 3U);
            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aIngress, 18U) + RotL64(aCarry, 37U)) ^ (RotL64(aPrevious, 5U) ^ RotL64(aCross, 53U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
            aOrbiterH = ((aWandererF + RotL64(aIngress, 41U)) + RotL64(aCarry, 11U)) + 0x3B7AD5D47AC2ABACULL;
            aOrbiterI = ((aWandererA + RotL64(aScatter, 5U)) + RotL64(aCarry, 53U)) + 0x1A52255828874365ULL;
            aOrbiterC = (aWandererK + RotL64(aCross, 60U)) + 0xE241737E1679333EULL;
            aOrbiterD = (((aWandererD + RotL64(aPrevious, 27U)) + RotL64(aCarry, 37U)) + 0x07C666759D233951ULL) + aTwistOrbiterAssignSaltA[((aIndex + 13U)) & S_SALT1];
            aOrbiterJ = (aWandererB + RotL64(aIngress, 13U)) + 0x5AEF4B5D841E3CABULL;
            aOrbiterE = ((aWandererE + RotL64(aScatter, 21U)) + 0x96534BDBF2D2E3DAULL) + aTwistOrbiterAssignSaltE[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterK = (aWandererJ + RotL64(aCross, 51U)) + 0x6D5D6192C9462D65ULL;
            //
            aOrbiterH = (aOrbiterH + aOrbiterI) + 0x932EC72316155172ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterH) ^ 0x38E39B064797B28AULL) ^ aTwistOrbiterUpdateSaltB[((aIndex + 23U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x0BCC550926ADF819ULL), 29U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterJ) + 0x45F758B669D37E85ULL) + aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 19U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterD) ^ 0xF040AC4384496B45ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xD240AEF58A12CBB1ULL), 11U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterD) + 0xF6220743B2C0AFB0ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterK) ^ 0x0E4AFABA4DB57773ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x4F9CD61CAFBBA225ULL), 51U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0xE631085E66553D13ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterJ) ^ 0x995229CEB2625B28ULL) ^ aTwistOrbiterUpdateSaltC[((aIndex + 9U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x702FC105A394AC63ULL), 3U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterC) + 0x5E5222B6FDCED09AULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterI) ^ 0xEF9EDE381D92A9F8ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xCA56696ABA1E51D7ULL), 43U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterK) + 0x93716CDC08C7239CULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterC) ^ 0x0C06C40DE20B444EULL;
            aOrbiterD = RotL64((aOrbiterD * 0xEC19EEA548D35387ULL), 23U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterH) + 0x14AA97275FD3C9D3ULL) + aTwistOrbiterUpdateSaltF[((aIndex + 18U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterE) ^ 0xDB3B815170992A10ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x87E90E026651256BULL), 35U);
            //
            aIngress = RotL64(aOrbiterK, 53U) ^ aOrbiterI;
            aIngress = aIngress + (RotL64(aOrbiterE, 3U) ^ aOrbiterD);
            aIngress = aIngress + (aOrbiterC ^ RotL64(aOrbiterJ, 11U));
            aIngress = aIngress + RotL64(aOrbiterH, 36U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererB = aWandererB + ((((RotL64(aCross, 3U) + RotL64(aOrbiterJ, 34U)) + aOrbiterK) + RotL64(aCarry, 35U)) + aTwistWandererUpdateSaltC[(((31U - aIndex) + 14U)) & S_SALT1]);
            aWandererF = aWandererF ^ ((RotL64(aPrevious, 57U) + RotL64(aOrbiterD, 41U)) + aOrbiterH);
            aWandererE = aWandererE + ((RotL64(aScatter, 35U) + aOrbiterJ) + RotL64(aOrbiterE, 5U));
            aWandererD = aWandererD ^ (((RotL64(aIngress, 21U) + RotL64(aOrbiterD, 57U)) + aOrbiterK) + aTwistWandererUpdateSaltE[(((31U - aIndex) + 17U)) & S_SALT1]);
            aWandererK = aWandererK + ((RotL64(aCross, 12U) + aOrbiterI) + RotL64(aOrbiterH, 27U));
            aWandererJ = aWandererJ ^ ((RotL64(aIngress, 47U) + aOrbiterK) + RotL64(aOrbiterC, 51U));
