            aIngress = TwistMix64::DiffuseB(aIngress);
            //
            aCross = (RotL64(aFuseLaneB[((S_BLOCK1 - aIndex + 28141U)) & S_BLOCK1], 19U) ^ RotL64(aWaterLaneC[((S_BLOCK1 - aIndex + 29445U)) & S_BLOCK1], 56U));
            aCross ^= RotL64(pSnowLaneB[((S_BLOCK1 - aIndex + 26305U)) & S_BLOCK1], 41U);
            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aCross, 3U) ^ RotL64(aPrevious, 19U)) + (RotL64(aCarry, 52U) ^ RotL64(aIngress, 39U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterH = (((aWandererD + RotL64(aScatter, 41U)) + RotL64(aCarry, 37U)) + 0xC4E56FD577B2352EULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterG = ((aWandererF + RotL64(aPrevious, 21U)) + RotL64(aCarry, 51U)) + 0x720D884D77C6C6B3ULL;
            aOrbiterF = (((aWandererK + RotL64(aCross, 47U)) + RotL64(aCarry, 11U)) + 0xA840AE7926417D99ULL) + aTwistOrbiterAssignSaltF[((aIndex + 23U)) & S_SALT1];
            aOrbiterD = (aWandererB + RotL64(aIngress, 57U)) + 0xBD36E3275F03E69EULL;
            aOrbiterB = (aWandererA + RotL64(aCross, 3U)) + 0x1C822A1F0E1B2F38ULL;
            aOrbiterJ = (aWandererE + RotL64(aScatter, 35U)) + 0xE96338CC22B96E72ULL;
            aOrbiterC = (aWandererC + RotL64(aIngress, 28U)) + 0xA5186D513B824C3AULL;
            //
            aOrbiterH = (aOrbiterH + aOrbiterG) + 0x5CCD494BCB102741ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterH) ^ 0x59BF2DB91F08D7A2ULL) ^ aTwistOrbiterUpdateSaltA[((aIndex + 7U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x8F6F53641AA6A5C7ULL), 29U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterH) + 0x98852155E75771B6ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterD) ^ 0xB0424E183AAF8E64ULL) ^ aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 24U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x345718C9E1140573ULL), 11U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterF) + 0x2E1F390FCE2A2179ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterG) ^ 0xAF3AA70484A5AF72ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xC9F6E472A799703DULL), 23U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0x0E8971BB498CDAEBULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterB) ^ 0xD89D12F0E204A3D8ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x920CBA39958E2AF9ULL), 5U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterD) + 0xDB93B618E2BB6BF3ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterC) ^ 0x51C9D0BBC4B0E65DULL;
            aOrbiterH = RotL64((aOrbiterH * 0x22E2133C28CE9869ULL), 41U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterB) + 0xA742D83038CB35E3ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterF) ^ 0x2DAD2BC8FAC3E0D0ULL) ^ aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x4956AAC12B070417ULL), 35U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterC) + 0x57AB57853D47A502ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterJ) ^ 0x6DB70899C087C712ULL) ^ aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xEDCA30E9848A5FD7ULL), 51U);
            //
            aIngress = aOrbiterF ^ RotL64(aOrbiterH, 28U);
            aIngress = aIngress + (RotL64(aOrbiterD, 51U) ^ aOrbiterC);
            aIngress = aIngress + (aOrbiterG ^ RotL64(aOrbiterJ, 11U));
            aIngress = aIngress + RotL64(aOrbiterB, 5U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererB = aWandererB ^ ((RotL64(aPrevious, 29U) + RotL64(aOrbiterG, 53U)) + aOrbiterH);
