            aWandererA = aWandererA ^ ((RotL64(aScatter, 18U) + RotL64(aOrbiterF, 47U)) + aOrbiterC);
            aWandererH = aWandererH + ((((RotL64(aCross, 27U) + aOrbiterC) + RotL64(aOrbiterE, 44U)) + RotL64(aCarry, 51U)) + aTwistWandererUpdateSaltA[(((31U - aIndex) + 12U)) & S_SALT1]);
