            aWandererD = aWandererD ^ (((RotL64(aCross, 5U) + aOrbiterA) + RotL64(aOrbiterG, 41U)) + aTwistWandererUpdateSaltF[((aIndex + 5U)) & S_SALT1]);
            aWandererB = aWandererB + ((RotL64(aScatter, 39U) + RotL64(aOrbiterJ, 20U)) + aOrbiterG);
