            //
            aOrbiterI = ((aOrbiterI + aOrbiterB) + 0x69B85FA5DFB81D40ULL) + aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterI) ^ 0x42AC57642A49F4DBULL;
            aOrbiterD = RotL64((aOrbiterD * 0x539367E649519BF3ULL), 23U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterG) + 0x271FD9689FB44912ULL;
