            aOrbiterK = RotL64((aOrbiterK * 0xCDEF66ABA438E90BULL), 43U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterJ) + 0xABB36931191A1B1DULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0x109602B34B2AF3D4ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x2436D74A0C9130C1ULL), 37U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterF) + 0x2D1785E65FADE0B6ULL;
