            aOrbiterG = RotL64((aOrbiterG * 0x1204CAC31D70CD7BULL), 41U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0x2DAA7DD0671354F4ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterJ) ^ 0xA8A8F222968E9CF6ULL;
