            aOrbiterJ = ((aWandererB + RotL64(aScatter, 51U)) + 0xAD18AADBEF4F29E3ULL) + aTwistOrbiterAssignSaltB[((aIndex + 22U)) & S_SALT1];
            aOrbiterB = (aWandererG + RotL64(aPrevious, 43U)) + 0x25ACBF5BCC6D3465ULL;
            aOrbiterC = (aWandererA + RotL64(aIngress, 19U)) + 0x5562D0E3E3FADE86ULL;
            aOrbiterH = (aWandererC + RotL64(aScatter, 57U)) + 0x94643A0BEFA4DC24ULL;
            aOrbiterE = ((aWandererH + RotL64(aPrevious, 47U)) + 0x7A694984D5D45543ULL) + aTwistOrbiterAssignSaltF[((aIndex + 15U)) & S_SALT1];
