            //
            aOrbiterA = (aOrbiterA + aOrbiterF) + 0xFCFBE712F9EE7868ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterA) ^ 0x3F530BFA6DA6F82DULL) ^ aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 29U)) & S_SALT1];
