            aOrbiterA = (((aWandererK + RotL64(aIngress, 39U)) + RotL64(aCarry, 35U)) + 0xCBF188338DCC5CEFULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterC = ((aWandererB + RotL64(aPrevious, 46U)) + RotL64(aCarry, 47U)) + 0x6CE59F6E9F6BB0AFULL;
            aOrbiterD = (aWandererD + RotL64(aIngress, 27U)) + 0x09EDE1DCAC575EC6ULL;
