            aOrbiterD = ((aOrbiterD + aOrbiterK) + 0x669845C503BD9612ULL) + aTwistOrbiterUpdateSaltF[((aIndex + 4U)) & S_SALT1];
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterD) ^ 0x5B86F61A1E028CE4ULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 11U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xF1826397D3758847ULL), 23U);
            //
