            aOrbiterK = RotL64((aOrbiterK * 0x07C9B860DAB3B1A3ULL), 47U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterJ) + 0x7094E3CD09D9DED2ULL) + aKeySpawnOrbiterUpdateSaltB[((aIndex + 23U)) & S_SALT1];
